package br.com.joaovictor.meuritmolite;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.provider.CalendarContract;import android.webkit.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> fileCallback;private String pendingBackup;private static final String ORIGIN="https://appassets.androidplatform.net";private static final int NOTIFY=71,IMPORT=72,EXPORT=73;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(0xfffaf9f5);getWindow().setNavigationBarColor(0xfffaf9f5);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=35)getWindow().getDecorView().setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets insets=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(insets.left,insets.top,insets.right,insets.bottom);return i;});web=new WebView(this);setContentView(web);WebView.setWebContentsDebuggingEnabled(false);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);s.setMediaPlaybackRequiresUserGesture(true);s.setTextZoom(100);s.setSafeBrowsingEnabled(true);web.addJavascriptInterface(new Host(),"AndroidHost");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(ORIGIN.equals(u.getScheme()+"://"+u.getHost()))return false;if("https".equals(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"https".equals(u.getScheme())||!"appassets.androidplatform.net".equals(u.getHost()))return blocked();String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(p.contains("..")||!p.matches("/[a-zA-Z0-9_./-]+"))return blocked();try{String mime=p.endsWith(".js")?"application/javascript":p.endsWith(".css")?"text/css":p.endsWith(".svg")?"image/svg+xml":p.endsWith(".ttf")?"font/ttf":p.endsWith(".woff2")?"font/woff2":p.endsWith(".woff")?"font/woff":p.endsWith(".txt")?"text/plain":"text/html";WebResourceResponse response=new WebResourceResponse(mime,"UTF-8",getAssets().open("site"+p));java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("Cache-Control","no-store");headers.put("X-Content-Type-Options","nosniff");response.setResponseHeaders(headers);return response;}catch(Exception e){return blocked();}}@Override public void onPageFinished(WebView v,String url){status();}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent in=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json");try{startActivityForResult(in,IMPORT);return true;}catch(Exception e){callback.onReceiveValue(null);fileCallback=null;return false;}}});Scheduler.channels(this);web.loadUrl(ORIGIN+"/index.html"+("OPEN_ALARMS".equals(getIntent().getAction())?"#alarmes":""));}
 private WebResourceResponse blocked(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream("Não disponível.".getBytes(StandardCharsets.UTF_8)));}
 void status(){if(web==null)return;Scheduler.reschedule(this);JSONObject st=Scheduler.status(this);try{JSONObject dismissed=new JSONObject();for(java.util.Map.Entry<String,?> e:Scheduler.prefs(this).getAll().entrySet())if(e.getKey().startsWith("dismissed:"))dismissed.put(e.getKey().substring(10),e.getValue());st.put("dismissed",dismissed);}catch(Exception ignored){}final String json=st.toString();runOnUiThread(()->web.evaluateJavascript("window.dispatchEvent(new CustomEvent('ritmo:native',{detail:"+json+"}))",null));}
 void notice(String text){runOnUiThread(()->Toast.makeText(this,text,Toast.LENGTH_LONG).show());}
 private void exactPermission(){if(!Scheduler.exact(this))new AlertDialog.Builder(this).setTitle("Permitir alarmes do Meu Ritmo?").setMessage("O Android precisa autorizar alarmes e lembretes para agendar cada aviso no horário escolhido, mesmo com o aplicativo fechado. Você pode continuar sem permitir, mas nenhum alarme exato será agendado.").setNegativeButton("Agora não",(d,w)->status()).setPositiveButton("Abrir permissão",(d,w)->{try{startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}catch(Exception e){notice("Abra as permissões de alarmes nas configurações do Android.");}}).show();else status();}
 private void permissions(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("Permitir avisos e controles de alarme?").setMessage("As notificações mostram qual alarme está tocando e permitem parar ou adiar sem abrir o aplicativo. A permissão é necessária para ativar os agendamentos nesta versão.").setNegativeButton("Agora não",(d,w)->status()).setPositiveButton("Continuar",(d,w)->{if(Scheduler.prefs(this).getBoolean("askedNotifications",false)&&!shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS))startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));else{Scheduler.prefs(this).edit().putBoolean("askedNotifications",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFY);}}).show();}else if(!Scheduler.notifications(this))new AlertDialog.Builder(this).setTitle("Notificações desativadas").setMessage("Ative as notificações do Meu Ritmo nas configurações para permitir os alarmes.").setNegativeButton("Voltar",null).setPositiveButton("Abrir configurações",(d,w)->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))).show();else exactPermission();}
 @Override public void onRequestPermissionsResult(int request,String[]permissions,int[]results){super.onRequestPermissionsResult(request,permissions,results);if(request==NOTIFY){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)exactPermission();else status();}}
 @Override protected void onResume(){super.onResume();if(web!=null)status();}
 @Override protected void onNewIntent(Intent in){super.onNewIntent(in);setIntent(in);if("OPEN_ALARMS".equals(in.getAction()))web.evaluateJavascript("location.hash='alarmes'",null);}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const d=document.querySelector('dialog[open]');if(d){d.close();return 'dialog'}if(location.hash&&location.hash!=='#hoje'){location.hash='hoje';return 'area'}return 'exit'})()",result->{if("\"exit\"".equals(result))new AlertDialog.Builder(this).setTitle("Fechar Meu Ritmo Lite?").setMessage("Os alarmes autorizados continuam agendados no Android. Parada forçada nas configurações interrompe os avisos até reabrir o aplicativo.").setNegativeButton("Continuar aqui",null).setPositiveButton("Fechar",(d,w)->finish()).show();});}
 @Override protected void onActivityResult(int request,int result,Intent in){super.onActivityResult(request,result,in);if(request==IMPORT&&fileCallback!=null){fileCallback.onReceiveValue(result==RESULT_OK&&in!=null?new Uri[]{in.getData()}:null);fileCallback=null;}if(request==EXPORT&&result==RESULT_OK&&in!=null&&pendingBackup!=null){try(OutputStream out=getContentResolver().openOutputStream(in.getData())){out.write(pendingBackup.getBytes(StandardCharsets.UTF_8));notice("Backup salvo no arquivo escolhido.");}catch(Exception e){notice("Não foi possível salvar o backup.");}finally{pendingBackup=null;}}}
 public class Host {
  @JavascriptInterface public String getStatus(){return Scheduler.status(MainActivity.this).toString();}
  @JavascriptInterface public void requestPermissions(){runOnUiThread(()->permissions());}
  @JavascriptInterface public void sync(String raw){if(raw==null||raw.length()>2000000)return;try{Scheduler.sync(MainActivity.this,raw);runOnUiThread(()->status());}catch(Exception e){notice("Não foi possível atualizar os alarmes. Confira os horários e permissões.");}}
  @JavascriptInterface public void testAlarm(){runOnUiThread(()->{if(!Scheduler.exact(MainActivity.this)||!Scheduler.notifications(MainActivity.this)){permissions();return;}try{JSONObject i=new JSONObject().put("id","native-test").put("title","Teste de alarme do Meu Ritmo").put("type","alarm").put("date",java.time.LocalDate.now().toString()).put("time",java.time.LocalTime.now().plusSeconds(10).withNano(0).toString()).put("repeat","none").put("days",new JSONArray()).put("skip",new JSONArray()).put("completed",new JSONArray()).put("enabled",true);JSONArray a=new JSONArray(Scheduler.prefs(MainActivity.this).getString("items","[]"));JSONArray clean=new JSONArray();for(int n=0;n<a.length();n++)if(!"native-test".equals(a.getJSONObject(n).optString("id")))clean.put(a.get(n));clean.put(i);Scheduler.prefs(MainActivity.this).edit().putString("items",clean.toString()).apply();Scheduler.schedule(MainActivity.this,"native-test",System.currentTimeMillis()+10000,"Teste de alarme do Meu Ritmo",true);notice("Alarme de teste agendado para daqui a 10 segundos.");}catch(Exception e){notice("Não foi possível testar o alarme.");}});}
  @JavascriptInterface public void dismissAlarm(String id,boolean snooze){if(id==null||id.length()>80)return;try{JSONArray a=new JSONArray(Scheduler.prefs(MainActivity.this).getString("items","[]"));for(int n=0;n<a.length();n++){JSONObject i=a.getJSONObject(n);if(id.equals(i.optString("id"))){Intent in=new Intent(MainActivity.this,AlarmReceiver.class).setAction(snooze?"SNOOZE":"STOP").putExtra("id",id).putExtra("title",i.optString("title")).putExtra("sound",true);sendBroadcast(in);return;}}}catch(Exception ignored){}}
  @JavascriptInterface public void backup(String json){if(json==null||json.length()>2000000)return;runOnUiThread(()->{pendingBackup=json;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"meu-ritmo-lite-"+java.time.LocalDate.now()+".json"),EXPORT);}catch(Exception e){pendingBackup=null;notice("Nenhum aplicativo disponível para salvar arquivos.");}});}
  @JavascriptInterface public void calendar(String raw){try{JSONObject i=new JSONObject(raw);String title=i.getString("title"),body=i.optString("body");if(title.length()>160||body.length()>20000)return;ZoneId z=ZoneId.systemDefault();long start=LocalDate.parse(i.getString("date")).atTime(LocalTime.parse(i.getString("time"))).atZone(z).toInstant().toEpochMilli(),end=LocalDate.parse(i.getString("date")).atTime(LocalTime.parse(i.getString("end"))).atZone(z).toInstant().toEpochMilli();if(end<=start)return;runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,title).putExtra(CalendarContract.Events.DESCRIPTION,body).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,end));}catch(Exception e){notice("Nenhum calendário compatível encontrado no celular.");}});}catch(Exception e){notice("Confira a data e os horários antes de enviar ao calendário.");}}
 }
}
